def countCellsAtMost(grid, queries):
    m, n = len(grid), len(grid[0])
    out = []
    for q in queries:
        row, col, total = m - 1, 0, 0
        while row >= 0 and col < n:
            if grid[row][col] > q:
                row -= 1
            else:
                total += row + 1
                col += 1
        out.append(total)
    return out
